<?php require '../config/conexion.php';require '../config/funciones.php';admin();$total=$pdo->query("SELECT COUNT(*) FROM denuncias")->fetchColumn();$rows=$pdo->query("SELECT * FROM denuncias ORDER BY id DESC LIMIT 50")->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><link rel="stylesheet" href="../assets/css/estilos.css"><title>Panel institucional</title></head><body><header><a class="brand" href="#">VJ · Panel institucional</a><a href="logout.php">Cerrar sesión</a></header><main class="wrap"><small>DASHBOARD DE INICIO</small><h1>Seguimiento institucional</h1><section class="cards"><div class="panel"><small>TOTAL DE DENUNCIAS</small><h2><?=$total?></h2></div><?php foreach(['Recibida','Turnada','Asignada','Reasignada'] as $st):$q=$pdo->prepare("SELECT COUNT(*) FROM denuncias WHERE estatus=?");$q->execute([$st]);?><div class="panel"><small><?=e(strtoupper($st))?></small><h2><?=$q->fetchColumn()?></h2></div><?php endforeach;?></section><section class="panel"><h2>Denuncias registradas</h2><div class="tablewrap"><table><tr><th>Folio</th><th>Municipio</th><th>Estatus</th><th>Fecha</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['folio'])?></td><td><?=e($r['municipio'])?></td><td><?=e($r['estatus'])?></td><td><?=e($r['fecha_registro'])?></td><td><a href="detalle.php?id=<?=$r['id']?>">Abrir</a></td></tr><?php endforeach;?></table></div></section></main></body></html>